var colorSection = document.evaluate("//*[contains(text(), 'Color') and not(./*)]", document, null, XPathResult.FIRST_QUALIFIED_NODE_TYPE, null).iterateNext();
if (colorSection) {
  // Walk up to find the section container
  let parent = colorSection.parentElement;
  while (parent && parent.tagName !== 'DIV') parent = parent.parentElement;
  // Scroll into view
  parent.scrollIntoView();
  return { found: true, text: colorSection.textContent, className: parent.className };
}
return { found: false };

var colorSection = document.querySelectorAll("#filterSections [view]"); var colorLinks = []; document.querySelectorAll("li").forEach(li => { var a = li.querySelector("a[aria-label*='Color'], a[aria-label*='color'], a[aria-label*='Black'], a[aria-label*='Black'], a[aria-label*='Apply']"); if (a && li.closest('#filterSections, [data-facet-name="Color"]') || (a.textContent && a.getAttribute('aria-label') && a.getAttribute('aria-label').toLowerCase().indexOf('black') !== -1)) { colorLinks.push({label: a.getAttribute('aria-label'), text: a.textContent.trim().substring(0,30), href: a.href}); } });
// Also get all color filter buttons with their labels
var colorButtons = document.querySelectorAll("a[data-hveid][aria-label]");
var result = [];
document.querySelectorAll("span[aria-label], a[aria-label]").forEach(el => {
  var lab = el.getAttribute('aria-label');
  if (lab && (lab.toLowerCase().includes('black') || lab.toLowerCase().includes('white') || lab.toLowerCase().includes('red') || lab.toLowerCase().includes('blue') || lab.toLowerCase().includes('grey') || lab.toLowerCase().includes('gray') || lab.toLowerCase().includes('green') || lab.toLowerCase().includes('yellow') || lab.toLowerCase().includes('orange') || lab.toLowerCase().includes('pink') || lab.toLowerCase().includes('brown') || lab.toLowerCase().includes('purple')) && el.closest('#filterSections, [data-facet-name="Color"]')) {
    result.push({label: lab, href: el.href || '', text: el.textContent.substring(0,30)});
  }
});
return result.slice(0, 20);

var result = [];
document.querySelectorAll("a[aria-label]").forEach(function(el) {
  var lab = el.getAttribute('aria-label') || '';
  var lower = lab.toLowerCase();
  if (lower.indexOf('apply') === 0 || lower.indexOf('remove') === 0) {
    // Check if it's in color section
    var parent = el.parentElement;
    while (parent && parent.tagName) {
      if (parent.textContent && parent.textContent.length < 500 && parent.previousElementSibling && parent.previousElementSibling.textContent === 'Color') {
        result.push({label: lab, href: el.href});
        break;
      }
      parent = parent.parentElement;
    }
  }
});
return result.slice(0, 30);

var result = [];
document.querySelectorAll("[view]").forEach(function(el) {
  var aria = el.getAttribute('aria-label') || el.getAttribute('title') || '';
  var alt = el.getAttribute('alt') || '';
  var text = (el.textContent || '').trim().substring(0, 30);
  if (aria || alt) {
    result.push({view: el.getAttribute('view'), aria: aria, alt: alt, text: text});
  }
});
return result.slice(0, 50);

var result = [];
var colorContainer = null;
var headings = document.querySelectorAll("div, h3, span, label");
for (var i = 0; i < headings.length; i++) {
  if (headings[i].textContent.trim() === 'Color' && headings[i].children.length === 0) {
    colorContainer = headings[i].parentElement;
    break;
  }
}
if (colorContainer) {
  var links = colorContainer.querySelectorAll("a");
  for (var j = 0; j < links.length; j++) {
    var a = links[j];
    result.push({
      aria: a.getAttribute('aria-label'),
      href: a.href ? a.href.substring(0, 150) : '',
      title: a.getAttribute('title'),
      text: a.textContent.trim().substring(0, 30)
    });
  }
}
return result;

var view = document.querySelector('[view="hhhib"]');
var parent = view;
while (parent && parent.tagName !== 'A') {
  parent = parent.parentElement;
  if (!parent) break;
}
if (parent) {
  return {
    found: true,
    href: parent.href,
    aria: parent.getAttribute('aria-label'),
    title: parent.getAttribute('title')
  };
}
return { found: false };

var view = document.querySelector('[view="hhhib"]');
var result = [];
var current = view;
while (current && current !== document.body) {
  result.push({
    tag: current.tagName,
    aria: current.getAttribute('aria-label'),
    title: current.getAttribute('title'),
    class: current.className,
    href: current.href
  });
  current = current.parentElement;
}
return result.slice(0, 8);

var views = document.querySelectorAll('[data-hveid], [class*="swatch"], li');
var result = [];
for (var i = 0; i < Math.min(views.length, 50); i++) {
  var el = views[i];
  var text = (el.textContent || '').trim();
  var aria = el.getAttribute('aria-label') || '';
  if (text.length < 50 && aria && (aria.toLowerCase().indexOf('color') !== -1 || aria.toLowerCase().indexOf('black') !== -1 || aria.toLowerCase().indexOf('apply') === 0 || aria.toLowerCase().indexOf('remove') === 0)) {
    result.push({tag: el.tagName, aria: aria.substring(0, 100), text: text.substring(0, 50)});
  }
}
return result.slice(0, 30);

var view = document.querySelectorAll("[view]")[i]; 
// Find view by content - look for the closest clickable element
var allViews = Array.from(document.querySelectorAll("[view]"));
var blackView = allViews.find(v => v.getAttribute('view') === 'hhhib');
if (blackView) {
  // walk up to find nearest a or button
  var parent = blackView;
  var chain = [];
  while (parent && parent !== document.body && chain.length < 6) {
    chain.push({
      tag: parent.tagName,
      href: parent.href ? parent.href.substring(0, 200) : null,
      aria: parent.getAttribute('aria-label'),
      role: parent.getAttribute('role'),
      id: parent.id,
      cls: parent.className.substring(0, 60)
    });
    parent = parent.parentElement;
  }
  return chain;
}
return {found: false};

var allViews = Array.from(document.querySelectorAll("[view]"));
var blackView = allViews.find(function(v) { return v.getAttribute('view') === 'hhhib'; });
if (blackView) {
  var parent = blackView;
  var chain = [];
  while (parent && parent !== document.body && chain.length < 6) {
    chain.push({
      tag: parent.tagName,
      href: parent.href ? parent.href.substring(0, 200) : null,
      aria: parent.getAttribute('aria-label'),
      role: parent.getAttribute('role'),
      id: parent.id,
      cls: (parent.className || '').substring(0, 60)
    });
    parent = parent.parentElement;
  }
  return chain;
}
return {found: false};

var allEls = document.querySelectorAll("*");
var found = [];
for (var i = 0; i < allEls.length; i++) {
  if (allEls[i].getAttribute('view') === 'hhhib') {
    found.push({
      tag: allEls[i].tagName,
      cls: (allEls[i].className || '').substring(0, 60),
      attrs: Array.from(allEls[i].attributes).map(a => a.name + '=' + a.value.substring(0, 50))
    });
  }
}
return {found: found.length, details: found.slice(0, 5)};

var appliedFilters = [];
document.querySelectorAll('#filter-p_36, #filter-p_72, [id^="p_n_size"], [id^="p_n_pt"]').forEach(function(el) {
  appliedFilters.push({
    id: el.id,
    text: el.textContent.trim().substring(0, 50)
  });
});
var colorApplied = [];
document.querySelectorAll('[id*="color"], [id*="size_two"]').forEach(function(el) {
  colorApplied.push({
    id: el.id,
    text: el.textContent.trim().substring(0, 80)
  });
});
return {appliedFilters: appliedFilters, colorApplied: colorApplied};
